  const auditBtn = document.createElement("button");
  auditBtn.type = "button";
  auditBtn.className = "ghost";
  auditBtn.textContent = "Open Audit Feed";
  auditBtn.addEventListener("click", () => {
    switchView("audit");
  });
  body.appendChild(auditBtn);
